-- Desk chords for Hyprland / Omarchy.
-- `desk shortcuts install` rewrites the marked block in
-- ~/.config/hypr/bindings.lua from the hosts and layouts on that machine.
-- This copy matches a mac / linux / tower desk with focus, split, and
-- mac-tower. o and hl are in scope when this file is pasted into
-- bindings.lua. A separate dofile will not see them if they are locals.
-- No sudo.

-- desk:shortcuts:begin
-- Generated by `desk shortcuts install`. Re-run after adding hosts or layouts.
-- Unbind only the Omarchy defaults these chords replace.
-- Omarchy moves a window silently to that workspace
hl.unbind("SUPER + ALT + SHIFT + 1")
-- Omarchy moves a window silently to that workspace
hl.unbind("SUPER + SHIFT + ALT + code:10")
-- Omarchy moves a window silently to that workspace
hl.unbind("SUPER + ALT + SHIFT + 2")
-- Omarchy moves a window silently to that workspace
hl.unbind("SUPER + SHIFT + ALT + code:11")
-- Omarchy moves a window silently to that workspace
hl.unbind("SUPER + ALT + SHIFT + 3")
-- Omarchy moves a window silently to that workspace
hl.unbind("SUPER + SHIFT + ALT + code:12")
-- Omarchy opens the file manager in the current directory
hl.unbind("SUPER + ALT + SHIFT + F")
-- Omarchy opens Grok
hl.unbind("SUPER + SHIFT + ALT + A")
o.bind("SUPER + ALT + SHIFT + 1", "Desk: Switch to mac", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk to mac'"))
o.bind("SUPER + ALT + SHIFT + 2", "Desk: Switch to linux", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk to linux'"))
o.bind("SUPER + ALT + SHIFT + 3", "Desk: Switch to tower", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk to tower'"))
o.bind("SUPER + ALT + 1", "Desk: focus", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk layout focus'"))
o.bind("SUPER + ALT + 2", "Desk: split", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk layout split'"))
o.bind("SUPER + ALT + 3", "Desk: mac-tower", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk layout mac-tower'"))
o.bind("SUPER + ALT + SHIFT + F", "Desk: Full", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk full'"))
o.bind("SUPER + ALT + SHIFT + P", "Desk: PBP", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk pbp'"))
o.bind("SUPER + ALT + U", "Desk: Auto layout", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk layout'"))
o.bind("SUPER + ALT + SHIFT + A", "Desk: Awake", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk awake toggle'"))
o.bind("SUPER + ALT + CTRL + 1", "Desk: mac on secondary", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk secondary mac'"))
o.bind("SUPER + ALT + CTRL + 2", "Desk: linux on secondary", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk secondary linux'"))
o.bind("SUPER + ALT + CTRL + 3", "Desk: tower on secondary", hl.dsp.exec_cmd("bash -lc 'export PATH=\"$HOME/.local/bin:$PATH\"; desk secondary tower'"))
-- desk:shortcuts:end
